
//#region src/yayson/adapter.ts
var Adapter = class {
	static get(model, key) {
		const obj = model;
		if (key) return obj[key];
		return obj;
	}
	static id(model) {
		const id = this.get(model, "id");
		if (id == null) return;
		return `${id}`;
	}
	static has(model, key) {
		return key in model;
	}
};
var adapter_default = Adapter;

//#endregion
